def _update_location_policies(self) -> None:
    """Update location mask policies based on mandate status and scope."""
    if self.authority.mandate_on:
        for loc in self.locations:
            loc.mask_policy = 'mandate' if loc.type != 'home' else 'none'
    else:
        for loc in self.locations:
            loc.mask_policy = 'recommended' if loc.type in ('store', 'public_transport', 'other_public') else 'none'

def _risk_signal(self, day: int) -> float:
    if self.risk_signal_mode == 'exogenous':
        period = max(1, self.risk_signal_period_days)
        return clamp01(self.risk_signal_initial + self.risk_signal_amplitude * math.sin(2.0 * math.pi * day / period))
    return clamp01(self.risk_signal_initial)

def _market_availability(self) -> Tuple[float, float]:
    if not self.retailers:
        return 0.0, self.mask_price
    total_inv = sum(r.inventory_level for r in self.retailers)
    avg_price = sum(r.price_per_mask for r in self.retailers) / len(self.retailers)
    capacity = len(self.retailers) * self.restock_lot_size
    availability = clamp01(total_inv / max(1.0, capacity))
    return availability, avg_price
